# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows


def make_student(last, first, section, email):
    return Student("id" + last, last, first, section, email)


class ContactRowTests(unittest.TestCase):
    def test_rows_sorted_and_aligned(self):
        rows = contact_rows(
            [
                make_student("Varrow", "Ines", "A", "iv@x"),
                make_student("Dun", "Piet", "BB", "pd@x"),
            ]
        )
        self.assertEqual(
            rows,
            [
                "Dun, Piet     BB  pd@x",
                "Varrow, Ines  A   iv@x",
            ],
        )

    def test_missing_email_names_student(self):
        students = [
            make_student("Dun", "Piet", "A", "pd@x.edu"),
            make_student("Quillon", "Sefa", "A", None),
        ]
        with self.assertRaises(ProjectError) as caught:
            contact_rows(students)
        message = str(caught.exception)
        self.assertIn("Quillon, Sefa", message)

    def test_blank_email_counts_as_missing(self):
        with self.assertRaises(ProjectError):
            blank = make_student("Dun", "P", "A", " ")
            contact_rows([blank])

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
